        { id = 4862, name = "En-Ay-Es-Tee-Why", level = 59, npc = "Kibler", npcID = 10260, map = 1428, x = 65.9, y = 21.9, objective = "Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.\n\nBy the sound of it, these eggs could be found near spiders.", rewards = { 12529 } },
        { id = 4729, name = "Kibler's Exotic Pets", level = 59, npc = "Kibler", npcID = 10260, map = 1428, x = 65.9, y = 21.9, objective = "Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler.", rewards = { 12264 } },
        { id = 5002, name = "Message to Maxwell", level = 59, faction = "Alliance", npc = "Bijou", npcID = 10257, objective = "Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell.", inside = true, pre = { 5001 } },
        { id = 4981, name = "Operative Bijou", level = 59, faction = "Horde", npc = "Lexlort", npcID = 9080, map = 1427, x = 85.3, y = 39.0, objective = "Travel to Blackrock Spire and find out what happened to Bijou." },
        { id = 4701, name = "Put Her Down", level = 59, faction = "Alliance", npc = "Helendis Riverhorn", npcID = 9562, map = 1428, x = 85.8, y = 68.9, objective = "Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg.", choices = { 15824, 15825, 15827 } },
        { id = 4724, name = "The Pack Mistress", level = 59, faction = "Horde", npc = "Galamav the Marksman", npcID = 9081, map = 1427, x = 85.4, y = 39.1, objective = "Slay Halycon, pack mistress of the Bloodaxe worg.", choices = { 15824, 15825, 15827 } },
        { id = 7761, name = "Blackhand's Command", level = 60, objective = "That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.\n\nThe letter indicates that General Drakkisath guards the brand. Perhaps you should investigate." },
        { id = 6602, name = "Blood of the Black Dragon Champion", level = 60, faction = "Horde", npc = "Rexxar", npcID = 10182, map = 1444, x = 46.4, y = 18.2, objective = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar.", rewards = { 16309 }, pre = { 4903, 4941, 4974, 6566, 6567, 6568, 6569, 6570, 6582, 6585, 6601 } },
        { id = 4765, name = "Delivery to Ridgewell", level = 60, faction = "Alliance", npc = "Mayara Brightwing", npcID = 9565, map = 1428, x = 84.8, y = 69.1, objective = "Bring Ridgewell's Crate to Remington Ridgewell in Stormwind.", choices = { 15861, 15860 }, pre = { 4764 } },
        { id = 4764, name = "Doomrigger's Clasp", level = 60, faction = "Alliance", npc = "Mayara Brightwing", npcID = 9565, map = 1428, x = 84.8, y = 69.1, objective = "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes." },
        { id = 6502, name = "Drakefire Amulet", level = 60, faction = "Alliance", npc = "Haleh", npcID = 10929, map = 1452, x = 54.5, y = 51.2, objective = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.", rewards = { 16309 }, pre = { 4185, 4186, 4223, 4224, 4241, 4242, 4264, 4282, 4322, 6402, 6403, 6501 } },
        { id = 4735, name = "Egg Collection", level = 60, npc = "Tinkee Steamboil", npcID = 10267, map = 1428, x = 65.2, y = 24.0, objective = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.", pre = { 4734 } },
        { id = 4734, name = "Egg Freezing", level = 60, npc = "Tinkee Steamboil", npcID = 10267, map = 1428, x = 65.2, y = 24.0, objective = "Use the Eggscilloscope Prototype on an egg in the Rookery.", rewards = { 12144 } },
        { id = 5047, name = "Finkle Einhorn, At Your Service!", level = 60, npc = "Finkle Einhorn", npcID = 10776, objective = "Talk to Malyfous Darkhammer in Everlook." },
        { id = 4974, name = "For The Horde!", level = 60, faction = "Horde", npc = "Thrall", npcID = 4949, map = 1454, x = 31.7, y = 37.8, objective = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar.", choices = { 13966, 13968, 13965 }, pre = { 4903, 4941 } },
        { id = 5089, name = "General Drakkisath's Command", level = 60, faction = "Alliance", objective = "Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes.", inside = true },
        { id = 5102, name = "General Drakkisath's Demise", level = 60, faction = "Alliance", npc = "Marshal Maxwell", npcID = 9560, map = 1428, x = 84.7, y = 69.0, objective = "Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done.", choices = { 13966, 13968, 13965 }, pre = { 5089 } },
        { id = 5081, name = "Maxwell's Mission", level = 60, faction = "Alliance", npc = "Marshal Maxwell", npcID = 9560, map = 1428, x = 84.7, y = 69.0, objective = "Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done.", choices = { 13958, 13959, 13961, 13962, 13963 }, pre = { 5001, 5002 } },
        { id = 4766, name = "Mayara Brightwing", level = 60, faction = "Alliance", npc = "Count Remington Ridgewell", npcID = 2285, map = 1453, x = 76.9, y = 47.8, objective = "Speak with Mayara Brightwing in the Burning Steppes." },
        { id = 8995, name = "Mea Culpa, Lord Valthalak", level = 60, npc = "Bodley", npcID = 16033, map = 1428, x = 32.3, y = 25.8, objective = "Use the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak.", pre = { 8949, 8950, 9015, 8951, 8960, 8961, 8962, 8966, 8970, 8986, 8989, 8994 } },
        { id = 4866, name = "Mother's Milk", level = 60, npc = "Ragged John", npcID = 9563, map = 1428, x = 65.0, y = 23.8, objective = "In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you.", rewards = { 15873 } },
        { id = 6569, name = "Oculus Illusions", level = 60, faction = "Horde", npc = "Myranda the Hag", npcID = 11872, map = 1422, x = 50.8, y = 77.8, objective = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.", pre = { 4903, 4941, 4974, 6566, 6567, 6568 } },
        { id = 4742, name = "Seal of Ascension", level = 60, npc = "Vaelan", npcID = 10296, objective = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.\n\nThe Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak  of the Bloodaxe." },
        { id = 4743, name = "Seal of Ascension", level = 60, npc = "Vaelan", npcID = 10296, objective = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.\n\nIt is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!", rewards = { 12344 }, pre = { 4742 } },
        { id = 4768, name = "The Darkstone Tablet", level = 60, faction = "Horde", npc = "Shadowmage Vivian Lagrave", npcID = 9078, map = 1427, x = 81.9, y = 39.1, objective = "Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.", choices = { 15861, 15860 } },
        { id = 5127, name = "The Demon Forge", level = 60, npc = "Lorax", npcID = 10918, map = 1452, x = 63.8, y = 73.8, objective = "Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.\n\nYou must also find the Unforged Rune Covered Breastplate.\n\nReturn both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.", rewards = { 12696, 9224, 12849 }, pre = { 5126 } },
        { id = 8966, name = "The Left Piece of Lord Valthalak's Amulet", level = 60, npc = "Bodley", npcID = 16033, map = 1428, x = 32.3, y = 25.8, objective = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", pre = { 8929, 8945, 8946, 8947, 8948, 8949, 8950, 9015, 8951, 8960, 8961, 8962 } },
        { id = 5160, name = "The Matron Protectorate", level = 60, npc = "Awbee", npcID = 10740, objective = "Travel to Winterspring and find Haleh. Give her Awbee's scale.", inside = true },
        { id = 8989, name = "The Right Piece of Lord Valthalak's Amulet", level = 60, npc = "Bodley", npcID = 16033, map = 1428, x = 32.3, y = 25.8, objective = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", pre = { 8947, 8948, 8949, 8950, 9015, 8951, 8960, 8961, 8962, 8966, 8970, 8986 } },
        { id = 4907, name = "Tinkee Steamboil", level = 60, npc = "Felnok Steelspring", npcID = 10468, map = 1452, x = 61.6, y = 38.6, objective = "Speak with Tinkee Steamboil.", pre = { 4726, 4808, 4809, 4810 } },
        { id = 4867, name = "Urok Doomhowl", level = 60, npc = "Warosh", npcID = 10799, objective = "Read Warosh's Scroll.  Bring Warosh's Mojo to Warosh.", rewards = { 15867 }, inside = true },
        { id = 4769, name = "Vivian Lagrave and the Darkstone Tablet", level = 60, faction = "Horde", npc = "Apothecary Zinge", npcID = 5204, map = 1458, x = 50.1, y = 68.0, objective = "Speak with Shadowmage Vivian Lagrave." },
        { id = 4903, name = "Warlord's Command", level = 60, faction = "Horde", objective = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.", choices = { 13958, 13959, 13961, 13962, 13963 }, inside = true },
    },
    [230] = {
        { id = 4295, name = "Rocknot's Ale", level = 1, npc = "Private Rocknot", npcID = 9503, inside = true },
        { id = 3981, name = "Commander Gor'shak", level = 52, faction = "Horde", npc = "Galamav the Marksman", npcID = 9081, map = 1427, x = 85.4, y = 39.1, objective = "Find Commander Gor'shak in Blackrock Depths.\n\nYou recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.", pre = { 3906 } },
        { id = 3801, name = "Dark Iron Legacy", level = 52, npc = "Franclorn Forgewright", npcID = 8888, map = 1428, x = 29.0, y = 28.9, objective = "Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major." },
        { id = 3802, name = "Dark Iron Legacy", level = 52, npc = "Franclorn Forgewright", npcID = 8888, map = 1428, x = 29.0, y = 28.9, objective = "Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.", rewards = { 11000 }, pre = { 3801 } },
        { id = 4081, name = "KILL ON SIGHT: Dark Iron Dwarves", level = 52, faction = "Horde", npc = "WANTED", map = 1427, x = 82.9, y = 38.7, objective = "Venture to Blackrock Depths and destroy the vile aggressors!\n\nWarlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete." },
        { id = 4136, name = "Ribbly Screwspigot", level = 53, npc = "Yuka Screwspigot", npcID = 9544, map = 1428, x = 66.1, y = 22.0, objective = "Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.", choices = { 11865, 11963, 12049 } },
        { id = 4324, name = "Yuka Screwspigot", level = 53, npc = "Yorba Screwspigot", npcID = 9706, map = 1446, x = 67.0, y = 24.0, objective = "Speak with Yuka Screwspigot in the Burning Steppes." },
        { id = 4242, name = "Abandoned Hope", level = 54, faction = "Alliance", npc = "Marshal Windsor", npcID = 9023, objective = "Give Marshal Maxwell the bad news.", choices = { 12018, 12021, 12041 }, inside = true, pre = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241 } },
        { id = 4082, name = "KILL ON SIGHT: High Ranking Dark Iron Officials", level = 54, faction = "Horde", npc = "KILL ON SIGHT", map = 1427, x = 83.1, y = 37.9, objective = "Venture to Blackrock Depths and destroy the vile aggressors!\n\nWarlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.", pre = { 4081 } },
        { id = 4241, name = "Marshal Windsor", level = 54, faction = "Alliance", npc = "Marshal Maxwell", npcID = 9560, map = 1428, x = 84.7, y = 69.0, objective = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.\n\nYou recall Ragged John talking about Windsor being dragged off to a prison.", pre = { 4182, 4183, 4184, 4185, 4186, 4223, 4224 } },
        { id = 4002, name = "The Eastern Kingdom", level = 54, faction = "Horde", npc = "Thrall", npcID = 4949, map = 1454, x = 31.7, y = 37.8, objective = "Speak with Thrall if you are prepared to take on the mission he has planned.", pre = { 3906, 3981, 3982, 4001 } },
        { id = 7201, name = "The Last Element", level = 54, faction = "Horde", npc = "Shadowmage Vivian Lagrave", npcID = 9078, map = 1427, x = 81.9, y = 39.1, objective = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.", rewards = { 12038 } },
        { id = 4201, name = "The Love Potion", level = 54, npc = "Mistress Nagmara", npcID = 9500, objective = "Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.", choices = { 11962, 11866 }, inside = true },
        { id = 3982, name = "What Is Going On?", level = 54, faction = "Horde", npc = "Commander Gor'shak", npcID = 9020, objective = "Defend Gor'shak.", inside = true, pre = { 3906, 3981 } },
        { id = 4001, name = "What Is Going On?", level = 54, faction = "Horde", npc = "Commander Gor'shak", npcID = 9020, objective = "Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.\n\nYou recall Gor'shak mentioning that Kharan is being held in a cell nearby.", inside = true, pre = { 3906, 3981, 3982 } },
        { id = 4126, name = "Hurley Blackbreath", level = 55, faction = "Alliance", npc = "Ragnar Thunderbrew", npcID = 1267, map = 1426, x = 46.8, y = 52.4, objective = "Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.", rewards = { 12003 }, choices = { 11964, 12000 } },
        { id = 4134, name = "Lost Thunderbrew Recipe", level = 55, faction = "Horde", npc = "Shadowmage Vivian Lagrave", npcID = 9078, map = 1427, x = 81.9, y = 39.1, objective = "Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.", rewards = { 3928, 6149 }, choices = { 11964, 12000 } },
        { id = 4128, name = "Ragnar Thunderbrew", level = 55, faction = "Alliance", npc = "Enohar Thunderbrew", npcID = 9540, map = 1419, x = 63.6, y = 20.6, objective = "Speak with Ragnar Thunderbrew." },
        { id = 4123, name = "The Heart of the Mountain", level = 55, npc = "Maxwort Uberglint", npcID = 9536, map = 1428, x = 65.2, y = 23.9, objective = "Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes." },
        { id = 4083, name = "The Spectral Chalice", level = 55, npc = "Spectral Chalice", inside = true },
        { id = 4133, name = "Vivian Lagrave", level = 55, faction = "Horde", npc = "Apothecary Zinge", npcID = 5204, map = 1458, x = 50.1, y = 68.0, objective = "Speak with Shadowmaster Vivian Lagrave in Kargath." },
        { id = 3907, name = "Disharmony of Fire", level = 56, faction = "Horde", npc = "Thunderheart", npcID = 9084, map = 1427, x = 82.4, y = 39.7, objective = "Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.", choices = { 12113, 12114, 12112, 12115 }, pre = { 3906 } },
        { id = 4263, name = "Incendius!", level = 56, faction = "Alliance", npc = "Jalinda Sprig", npcID = 9561, map = 1428, x = 85.4, y = 70.1, objective = "Find Lord Incendius in Blackrock Depths and destroy him!", choices = { 12113, 12114, 12112, 12115 }, pre = { 4262 } },
        { id = 4286, name = "The Good Stuff", level = 56, faction = "Alliance", npc = "Oralius", npcID = 9177, map = 1428, x = 84.6, y = 68.7, objective = "Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions.", rewards = { 11883 } },
        { id = 4264, name = "A Crumpled Up Note", level = 58, faction = "Alliance", objective = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all.", inside = true, pre = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241, 4242 } },
        { id = 4282, name = "A Shred of Hope", level = 58, faction = "Alliance", npc = "Marshal Windsor", npcID = 9023, objective = "Return Marshal Windsor's Lost Information.\n\nMarshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge.", inside = true, pre = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241, 4242, 4264 } },
        { id = 4024, name = "A Taste of Flame", level = 58, npc = "Cyrus Therepentous", npcID = 9459, map = 2548, x = 23.9, y = 36.5, objective = "Travel to Blackrock Depths and slay Bael'Gar.\n\nYou only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.\n\nReturn the Encased Fiery Essence to Cyrus Therepentous.", choices = { 12066, 12082, 12083 }, pre = { 4023 } },
        { id = 4122, name = "Grark Lorkrub", level = 58, faction = "Horde", npc = "Lexlort", npcID = 9080, map = 1427, x = 85.3, y = 39.0, objective = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.\n\nWhen you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody." },
        { id = 4322, name = "Jail Break!", level = 58, faction = "Alliance", npc = "Marshal Windsor", npcID = 9023, objective = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.", rewards = { 12065 }, choices = { 12061, 12062 }, inside = true, pre = { 4182, 4183, 4184, 4185, 4186, 4223, 4224, 4241, 4242, 4264, 4282 } },
        { id = 4132, name = "Operation: Death to Angerforge", level = 58, faction = "Horde", npc = "Warlord Goretooth", npcID = 9077, map = 1427, x = 85.2, y = 38.8, objective = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.", rewards = { 12059 }, pre = { 4122, 4121 } },
        { id = 4121, name = "Precarious Predicament", level = 58, faction = "Horde", npc = "Grark Lorkrub", npcID = 9520, map = 1428, x = 40.2, y = 34.2, objective = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.\n\nYou recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.\n\nYou will also be required to hand over your Thorium Shackles to Lexlort.", pre = { 4122 } },
        { id = 4063, name = "The Rise of the Machines", level = 58, faction = "Horde", npc = "Lotwil Veriatus", npcID = 2921, map = 1418, x = 25.9, y = 44.9, objective = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.", choices = { 12109, 12110, 12108, 12111 }, pre = { 4061, 4062 } },
        { id = 4341, name = "Kharan Mighthammer", level = 59, faction = "Alliance", npc = "King Magni Bronzebeard", npcID = 2784, map = 1455, x = 39.1, y = 56.2, objective = "Travel to Blackrock Depths and find Kharan Mighthammer.\n\nThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.", pre = { 3702, 3701 } },
        { id = 4342, name = "Kharan's Tale", level = 59, faction = "Alliance", npc = "Kharan Mighthammer", npcID = 9021, objective = "Listen as Kharan Mighthammer tells his story.", inside = true },
        { id = 4361, name = "The Bearer of Bad News", level = 59, faction = "Alliance", npc = "Kharan Mighthammer", npcID = 9021, objective = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard.", inside = true, pre = { 3702, 3701, 4341 } },
        { id = 4362, name = "The Fate of the Kingdom", level = 59, faction = "Alliance", npc = "King Magni Bronzebeard", npcID = 2784, map = 1455, x = 39.1, y = 56.2, objective = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.", pre = { 3702, 3701, 4341, 4361 } },
        { id = 4363, name = "The Princess's Surprise", level = 59, faction = "Alliance", npc = "Princess Moira Bronzebeard", npcID = 8929, objective = "Return to Ironforge and speak with King Magni Bronzebeard.", choices = { 12548, 12543 }, inside = true, pre = { 3702, 3701, 4341, 4361, 4362 } },
        { id = 4003, name = "The Royal Rescue", level = 59, faction = "Horde", npc = "Thrall", npcID = 4949, map = 1454, x = 31.7, y = 37.8, objective = "Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell.", pre = { 3906, 3981, 3982, 4001, 4002 } },
        { id = 7604, name = "A Binding Contract", level = 60, objective = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.", rewards = { 18592 }, inside = true },
        { id = 9015, name = "The Challenge", level = 60, npc = "Falrin Treeshaper", npcID = 16032, objective = "Travel to the Ring of the Law in Blackrock Depths and place the Banner of Provocation in its center as you are sentenced by High Justice Grimstone.  Slay Theldren and his gladiators and return to Anthion Harmon in the Eastern Plaguelands with the first piece of Lord Valthalak's amulet.", pre = { 8924, 8925, 8928, 8977, 8926, 8929, 8945, 8946, 8947, 8948, 8949, 8950 } },
        { id = 4004, name = "The Princess Saved?", level = 60, faction = "Horde", npc = "Princess Moira Bronzebeard", npcID = 8929, objective = "Return to Thrall!", choices = { 12544, 12545 }, inside = true, pre = { 3906, 3981, 3982, 4001, 4002, 4003 } },
    },
    [289] = {
        { id = 5582, name = "Healthy Dragon Scale", level = 58, objective = "Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands.", inside = true, pre = { 5529 } },
